template<class F>void refuses(F f){bool caught=false;try{f();}catch(const std::exception&){caught=true;}need(caught,"closed refusal missing");}
std::uint64_t bits(double d){std::uint64_t b;std::memcpy(&b,&d,8);return b;}
m::GapPicOptions options(){m::GapPicOptions o;o.nx=o.ny=45;o.width_m=o.gap_m=.009;o.depth_m=.025;o.short_z_m=0;o.feed_z_m=.025;o.finite_axial_extent=o.finite_foils=true;o.lower_foil={.002,.007,.0018,.002};o.upper_foil={.002,.007,.007,.0072};return o;}
cg::FrameBinding frame(const cg::Geometry&g,const char*name="canonical-pilot-xyz"){return {g,nw::sha(name),nw::sha("original-native-centered-xy")};}
pc::Vec electron_u(double E){const double x=E*pc::qe/(9.1093837139e-31*pc::c*pc::c);return {pc::c*std::sqrt(x*(x+2)),0,0};}
m::ArenaRateEntry entry(std::uint64_t id,const char*state,pc::Vec position,double w=1){m::ArenaRateEntry e;e.packet_id="packet/"+std::to_string(id);e.state=state;e.native.id=id;e.native.position_m=position;e.native.weight=w;e.native.mass_kg=std::string(state)=="electron"?9.1093837139e-31:2.9915e-26;e.native.charge_C=std::string(state)=="electron"?-pc::qe:0;e.native.proper_velocity_m_s=std::string(state)=="electron"?electron_u(100):pc::Vec{0,0,0};return e;}
bool same(const pc::Candidate&a,const pc::Candidate&b){if(std::tie(a.projectile_id,a.target_id,a.channel_id,a.data_sha256,a.kernel_sha256,a.cell)!=std::tie(b.projectile_id,b.target_id,b.channel_id,b.data_sha256,b.kernel_sha256,b.cell))return false;const double av[]={a.event_weight,a.projectile_before,a.target_before,a.projectile_remainder.high,a.projectile_remainder.low,a.target_remainder.high,a.target_remainder.low,a.rate_s,a.energy_eV,a.flux_m_s,a.sigma_m2,a.volume_m3},bv[]={b.event_weight,b.projectile_before,b.target_before,b.projectile_remainder.high,b.projectile_remainder.low,b.target_remainder.high,b.target_remainder.low,b.rate_s,b.energy_eV,b.flux_m_s,b.sigma_m2,b.volume_m3};for(int i=0;i<12;++i)if(bits(av[i])!=bits(bv[i]))return false;return true;}
