 for(auto mutation:{0,1,2,3,4,5,6}){auto bad=rows;if(mutation==0)bad.pop_back();if(mutation==1)bad[0].native.id=1;if(mutation==2)bad[0].native.weight=0;if(mutation==3)bad[0].native.position_m[0]=NAN;if(mutation==4)bad[0].native.proper_velocity_m_s[0]=NAN;if(mutation==5)bad[0].state="";if(mutation==6)bad[0].native.position_m={.004,.002,.0125};refuses([&]{a.occupied_cells(bad,binding);});}
