 std::mt19937_64 rng(117);std::uniform_real_distribution<double>x(0,.009),z(0,.025);std::size_t accepted=0;for(int i=0;i<30000;++i){pc::Vec p{x(rng),x(rng),z(rng)};bool solid=false;for(const auto&s:g.foils)solid|=p[0]>s.left_m&&p[0]<s.right_m&&p[1]>s.bottom_m&&p[1]<s.top_m;if(solid){refuses([&]{a.locate({p});});continue;}auto id=a.locate({p});need(id==b.locate({p})&&a.physical_volume(id)>0,"graded deterministic lookup");++accepted;}
 for(const auto&s:g.foils){for(double xx:{s.left_m,s.right_m})for(double yy:{s.bottom_m,s.top_m})refuses([&]{a.locate({{xx,yy,.0125}});});for(pc::Vec p:std::vector<pc::Vec>{{.004,s.bottom_m,.0125},{.004,s.top_m,.0125},{s.left_m,(s.bottom_m+s.top_m)*.5,.0125},{s.right_m,(s.bottom_m+s.top_m)*.5,.0125}})refuses([&]{a.locate({p});});need(a.physical_volume(a.locate({{.004,s.bottom_m-1e-9,.0125}}))>0&&a.physical_volume(a.locate({{.004,s.top_m+1e-9,.0125}}))>0,"one-nm vacuum strip retained");}
 need(a.locate({{.004,.004,1e-9}})!=a.locate({{.004,.004,.025-1e-9}}),"full-height axial distinction");refuses([&]{a.locate({{.004,.004,std::nextafter(.025,INFINITY)}});});cg::AtlasLimits cap;cap.geometric_bins=1;refuses([&]{cg::CollisionAtlas::graded(g,f,cfg,cap);});cap={};cap.xy_nodes=1;refuses([&]{cg::CollisionAtlas::graded(g,f,cfg,cap);});auto shifted=g;shifted.low_m[2]=-.0125;shifted.high_m[2]=.0125;auto other=cg::CollisionAtlas::graded(shifted,frame(shifted),cfg);need(a.identity()!=other.identity(),"axial frame not fingerprinted");auto different=cg::CollisionAtlas::graded(g,frame(g,"foreign canonical frame"),cfg);need(a.identity()!=different.identity(),"canonical frame not fingerprinted");pass("Native graded geometry: deterministic identity and "+std::to_string(accepted)+" vacuum lookups; solid/face/corner/outer guards; 1 nm vacuum retained; full 25 mm z and frame/topology identities");
 static_assert(!std::is_convertible_v<cg::NativeCenteredXYPointSI,cg::CanonicalPointSI>);const cg::CanonicalPointSI point{{.004,.006,.003}};auto native=f.native_field_point(point);need(bits(native.value[0])==bits(point.value[0]-.0045)&&bits(native.value[1])==bits(point.value[1]-.0045)&&bits(native.value[2])==bits(point.value[2]),"original centered native XY arithmetic once");need(bits(point.value[0])==bits(.004)&&a.locate(point)==a.locate({{.004,.006,.003}}),"canonical particle changed by adapter");cg::FrameBinding canonical(nw::sha("canonical-TOTAL-fields"));auto canonical_atlas=cg::CollisionAtlas::graded(g,canonical,cfg);need(canonical_atlas.locate(point)==a.locate(point),"canonical-only frame shifts collision positions");refuses([&]{canonical.native_field_point(point);});pass("Strong canonical/native point types: original x/y minus4.5mm bits exactly once; canonical-only TOTAL-E/B frame applies no transform and refuses a native-field map");
